import {tools,categories,icon} from './catalog.mjs';
import {escapeHTML as e} from './core.mjs';
import {blogIndex,blogCard} from './blog.mjs';
const route=id=>`./tools/${id}/`;
const picks=['image-converter','pdf-merge','calculator','qr-code','background-remover','ielts-overall'];
const collectionIds=['images','pdf','calculators','creators','study','developer'];
export const homeCard=(t,favorites=new Set())=>`<article class="tool-card cat-${t.category}"><button class="star-btn ${favorites.has(t.id)?'saved':''}" data-star="${t.id}" aria-label="${favorites.has(t.id)?'Remove':'Add'} ${e(t.title)} ${favorites.has(t.id)?'from':'to'} favorites" aria-pressed="${favorites.has(t.id)}">${icon('star')}</button><a href="${route(t.id)}"><span class="tool-icon">${icon(t.icon)}</span><h3>${e(t.title)}</h3><p>${e(t.description)}</p><span class="card-open">LET’S GO ${icon('arrow')}</span></a></article>`;
function sculpture(){return `<div class="workshop-art" aria-label="Shortcuts to image conversion, QR codes and the scientific calculator"><div class="art-grid" aria-hidden="true"></div><div class="art-orbit" aria-hidden="true"></div><span class="art-caption">THE EVERYDAY OBJECTS / VOL. 01</span><span class="art-spark" aria-hidden="true">✳</span><a class="object-image" href="${route('image-converter')}" aria-label="Open image converter"><div class="object-toolbar"><span>01 — IMAGE LAB</span>${icon('arrow')}</div><div class="paper-picture"><span class="picture-sun"></span><span class="picture-mountain mountain-back"></span><span class="picture-mountain"></span><span class="picture-caption">a fresh perspective.</span></div><div class="format-badges"><span>PNG</span><b>→</b><span>JPEG</span><span>WEBP</span></div></a><a class="object-qr" href="${route('qr-code')}" aria-label="Open QR code generator"><span>MAKE A CONNECTION</span><div class="art-qr" aria-hidden="true"><i></i><i></i><i></i><b>✳</b></div><strong>Scan. Share. Go. ↗</strong></a><a class="object-calc" href="${route('calculator')}" aria-label="Open scientific calculator"><span>QUICK THINKING.</span><strong>24 × 7 <b>168</b></strong><div aria-hidden="true">${['7','8','9','÷','4','5','6','×'].map(n=>`<i>${n}</i>`).join('')}</div></a><span class="art-stamp">100% FREE<br><b>0% FUSS.</b></span><span class="art-coordinate">27.7172° N / MADE FOR EVERYWHERE</span></div>`;}
export function homeHTML(favorites=new Set(),layout='grid'){
return `<section class="atelier-hero"><div class="hero-edition"><span><i></i> THE INTERNET’S LITTLE WORKSHOP</span><span>OPEN TO EVERYONE, ALWAYS.</span></div><div class="atelier-hero-grid"><div class="atelier-intro"><h1>Less friction.<br>More <em>flow.</em><span class="headline-star" aria-hidden="true">✳</span></h1><p>Good tools get out of your way.<br>Meet ${tools.length} little shortcuts for whatever’s next.</p><form class="atelier-search" data-tool-search role="search" action="./tools/" method="get"><label class="sr-only" for="hero-query">Find a tool</label>${icon('search')}<input id="hero-query" name="q" type="search" placeholder="What are we making today?" autocomplete="off"><button type="submit" aria-label="Search tools">${icon('arrow')}</button></form><div class="atelier-suggestions"><span>A FEW IDEAS</span><a href="./tools/?q=image+compress">Shrink an image ↗</a><a href="./tools/?q=merge+pdf">Merge PDFs ↗</a><a href="./tools/?q=qr+code">Make a QR ↗</a></div></div>${sculpture()}</div><div class="workshop-manifesto"><span>${icon('check')} No subscriptions.</span><span>${icon('lock')} No account needed.</span><span>${icon('shield')} Your files stay yours.</span><a href="./tools/">FIND YOUR SHORTCUT <span>↓</span></a></div></section>
<section class="workshop-picks"><div class="index-heading"><span>01 / THE QUICK START</span><h2>Small tools. <em>Big energy.</em></h2><a href="./tools/">The full toolkit ${icon('arrow')}</a></div><div class="picks-grid">${picks.map((id,i)=>{const t=tools.find(t=>t.id===id);return `<a class="pick pick-${i}" href="${route(id)}"><div class="pick-top"><span>0${i+1}</span><span>${e(categories.find(c=>c.id===t.category).name)}</span>${icon('arrow')}</div><div class="pick-object" aria-hidden="true">${icon(t.icon)}<span>${['JPG','PDF','1+1','QR','CUT','7.5'][i]}</span></div><h3>${e(t.title)}</h3><p>${e(t.description)}</p></a>`;}).join('')}</div></section>
<section class="workshop-categories"><div><span class="index-label">02 / PICK YOUR PLAYGROUND</span><h2>What’s on<br> your <em>to-do?</em></h2><p>A place for every kind of task.</p></div><div class="category-index">${collectionIds.map((id,i)=>{const c=categories.find(c=>c.id===id);return `<a class="category-row" href="./categories/${id}/"><span class="category-number">0${i+1}</span><span class="category-name">${e(c.name)}</span><span class="category-total">${tools.filter(t=>t.category===id).length} TOOLS</span><span class="category-row-arrow">↗</span></a>`;}).join('')}</div></section>
<section class="recent-section" data-recent-section hidden><div class="section-head"><h2>Back to your work.</h2><button class="text-link" data-clear-recent>Clear history</button></div><div class="tool-grid" data-recent-grid></div></section>
<section class="workshop-create"><div><span class="index-label">A LITTLE SPACE TO EXPERIMENT</span><h2>Make it.<br><em>Make it yours.</em></h2><p>Screenshot frames. Quote cards. A fresh spark.<br>Your next idea starts with a little play.</p><a class="atelier-button" href="./categories/creators/">ENTER THE CREATIVE STUDIO ${icon('arrow')}</a></div><div class="create-poster" aria-hidden="true"><div class="poster-top"><span>NEPOCORE STUDIO</span><span>N° 001</span></div><span class="poster-word">MAKE<br>SOME<br><i>THING.</i></span><span class="poster-star">✳</span><span class="poster-foot">A WORK IN PROGRESS IS STILL A WORK OF ART.</span></div><span class="create-sticker" aria-hidden="true">NO RULES.<br>JUST IDEAS. ↗</span></section>
<section class="workshop-directory" id="all-tools"><div class="index-heading"><span>03 / THE TOOL INDEX</span><h2>Find your <em>next shortcut.</em></h2><span id="result-count" class="count-label">${tools.length} tools</span></div><form class="directory-search" data-tool-search role="search" action="./tools/" method="get"><label class="sr-only" for="directory-query">Find a tool by name or task</label><div><span>${icon('search')}</span><input id="directory-query" name="q" type="search" placeholder="Type a tool, a task, a little problem…"><button class="btn primary" type="submit">Find a tool ${icon('arrow')}</button></div></form><div class="tool-controls"><div class="chips-track" aria-label="Tool categories">${categories.slice(0,9).map(c=>`<a class="chip ${c.id==='all'?'active':''}" href="${c.id==='all'?'./tools/':`./categories/${c.id}/`}">${e(c.name)}</a>`).join('')}</div><div class="view-toggle"><button data-view="grid" class="${layout==='grid'?'active':''}" aria-label="Grid view" aria-pressed="${layout==='grid'}">${icon('grid')}</button><button data-view="list" class="${layout==='list'?'active':''}" aria-label="List view" aria-pressed="${layout==='list'}">${icon('list')}</button></div></div><div id="catalog-grid" class="tool-grid ${layout==='list'?'list':''}">${tools.slice(0,12).map(t=>homeCard(t,favorites)).join('')}</div><div class="catalog-more"><a class="atelier-button" href="./tools/">ALL ${tools.length} TOOLS. ALL YOURS. ${icon('arrow')}</a></div></section>
<section class="workshop-notes"><div class="index-heading"><span>04 / FIELD NOTES</span><h2>A little <em>know-how.</em></h2><a href="./blog/">All practical guides ${icon('arrow')}</a></div><div class="blog-grid">${[blogIndex[0],blogIndex[8],blogIndex[27]].map(blogCard).join('')}</div></section>
<aside class="workshop-privacy"><span class="privacy-seal">${icon('shield')}</span><div><span class="index-label">YOUR WORK IS YOUR BUSINESS.</span><h2>Built to help. Designed to respect.</h2><p>Files are processed in your browser. No accounts required.</p></div><a href="./privacy/">Our privacy approach ↗</a></aside>`;
}
